// ---- SAVES ----
// Each save is its own universe: one team, its own seasons and its own history on top of the 1826-2025 canon.
// Stored on this device (localStorage) and backed up to the artifact database; whichever copy is newer wins on load.
const SAVES_KEY='fn_saves_v1',saveKey=id=>'fn_save_'+id;let SAVES={active:null,list:[]},dbSaves=null;
function saveMeta(id,S){const r=S.stats&&S.stats.t&&S.stats.t[S.team]||{w:0,gp:0};return{id,team:S.team,num:S.num,year:seasonYear(S.num),phase:S.phase,w:r.w,l:(r.gp||0)-(r.w||0),updated:S.updated||Date.now()}}
function writeIndex(){LS.set(SAVES_KEY,JSON.stringify(SAVES))}
async function initSeasonStore(){try{SAVES=JSON.parse(LS.get(SAVES_KEY)||'null')||{active:null,list:[]}}catch(e){SAVES={active:null,list:[]}}
 LS.del(SKEY);pruneSaves();loadActive();
 try{const db=window.claude&&claude.use?await claude.use('db'):null,user=db&&claude.use?await claude.use('user'):null,uid=user?await user.id():null;if(!db||!uid)return;
  dbSaves={db,base:'data/users/'+uid+'/'};const idx=await db.doc(dbSaves.base+'saveindex').get();
  if(idx.exists){const remote=idx.data().list||[];for(const m of remote){const loc=SAVES.list.find(x=>x.id===m.id);if(!loc||(m.updated||0)>(loc.updated||0)){const d=await db.doc(dbSaves.base+'save_'+m.id).get();if(d.exists&&validSave(d.data().season)){LS.set(saveKey(m.id),JSON.stringify(d.data().season));if(loc)Object.assign(loc,m);else SAVES.list.push(m)}}}
   if(!SAVES.active&&idx.data().active)SAVES.active=idx.data().active;pruneSaves();loadActive();if(document.querySelector('#season.active'))renderSeason()}}catch(e){}}
// A save made before save slots existed (no histStart) is retired: it predates the current league history and playoff format.
function validSave(S){return !!(S&&S.v===4&&S.histStart&&S.num>=1)}
function pruneSaves(){const keep=[];for(const m of SAVES.list){let S=null;try{S=JSON.parse(LS.get(saveKey(m.id))||'null')}catch(e){}if(validSave(S))keep.push(m);else{LS.del(saveKey(m.id));if(dbSaves)dbSaves.db.doc(dbSaves.base+'save_'+m.id).delete().catch(()=>{})}}
 const changed=keep.length!==SAVES.list.length;SAVES.list=keep;if(SAVES.active&&!keep.find(m=>m.id===SAVES.active))SAVES.active=null;writeIndex();
 if(changed&&dbSaves)dbSaves.db.doc(dbSaves.base+'saveindex').set({active:SAVES.active,list:SAVES.list}).catch(()=>{})}
function loadActive(){try{SEASON=SAVES.active?JSON.parse(LS.get(saveKey(SAVES.active))||'null'):null}catch(e){SEASON=null}if(SEASON&&SEASON.v!==4)SEASON=null;syncRoster()}
async function saveSeason(){if(!SEASON||!SAVES.active)return;SEASON.updated=Date.now();LS.set(saveKey(SAVES.active),JSON.stringify(SEASON));const m=saveMeta(SAVES.active,SEASON),i=SAVES.list.findIndex(x=>x.id===m.id);if(i<0)SAVES.list.push(m);else SAVES.list[i]=m;writeIndex();
 if(dbSaves){try{await dbSaves.db.doc(dbSaves.base+'save_'+SAVES.active).set({season:SEASON});await dbSaves.db.doc(dbSaves.base+'saveindex').set({active:SAVES.active,list:SAVES.list})}catch(e){}}}
function deleteSave(id){SAVES.list=SAVES.list.filter(x=>x.id!==id);LS.del?LS.del(saveKey(id)):LS.set(saveKey(id),'null');if(SAVES.active===id){SAVES.active=null;SEASON=null}writeIndex();
 if(dbSaves){dbSaves.db.doc(dbSaves.base+'save_'+id).delete().catch(()=>{});dbSaves.db.doc(dbSaves.base+'saveindex').set({active:SAVES.active,list:SAVES.list}).catch(()=>{})}}
function standings(confId){const conf=LEAGUE.confs.find(c=>c.id===confId),rows={};for(const id of conf.teams)rows[id]={id,w:0,l:0,cw:0,cl:0,pf:0,pa:0,h2h:{},m:{},strk:''};
 for(const wk of SEASON.sched)for(const g of wk){if(!g.res)continue;const {hs,as}=g.res,hw=hs>as,W=hw?g.h:g.a,L=hw?g.a:g.h,inConf=!g.x;
  for(const [id,me,them,won] of [[g.h,hs,as,hw],[g.a,as,hs,!hw]]){const r=rows[id];if(!r)continue;r.pf+=me;r.pa+=them;if(won){r.w++;if(inConf)r.cw++;r.strk=r.strk[0]==='W'?'W'+(+r.strk.slice(1)+1):'W1'}else{r.l++;if(inConf)r.cl++;r.strk=r.strk[0]==='L'?'L'+(+r.strk.slice(1)+1):'L1'}}
  if(rows[W]&&inConf)rows[W].h2h[L]=1;if(inConf&&rows[g.h]&&rows[g.a]){rows[g.h].m[g.a]=(rows[g.h].m[g.a]||0)+hs-as;rows[g.a].m[g.h]=(rows[g.a].m[g.h]||0)+as-hs}}
 const all=Object.values(rows),hp=r=>{const g=all.filter(x=>x!==r&&x.cl===r.cl&&(x.cw+x.cl?x.cw/(x.cw+x.cl):.5)===(r.cw+r.cl?r.cw/(r.cw+r.cl):.5));return g.length?g.filter(x=>r.h2h[x.id]).length/g.length:0},
  // circular ties (A beat B, B beat C, C beat A): point margin in the games between the tied teams
  hm=r=>all.filter(x=>x!==r&&x.cl===r.cl&&x.cw===r.cw).reduce((a,x)=>a+(r.m[x.id]||0),0);
 // Order: conference win % (so 3-0 and 2-0 are equal), then losses, then head-to-head, then head-to-head point margin, then overall team strength
 // (talent + program history), then point differential.
 const pct=r=>r.cw+r.cl?r.cw/(r.cw+r.cl):.5,str=id=>{const t=TM(id);return t.ovr+(t.elite||0)*.8+prestige(id)*.6};
 return all.sort((a,b)=>(pct(b)-pct(a))||(a.cl-b.cl)||(hp(b)-hp(a))||(hm(b)-hm(a))||(str(b.id)-str(a.id))||((b.pf-b.pa)-(a.pf-a.pa))||(b.pf-a.pf))}
const myConf=()=>confOfId(SEASON.team);
const myDiv=()=>divOfConf(myConf().id);
function isMine(g){return g&&(g.h===SEASON.team||g.a===SEASON.team)}
function myGame(){const S=SEASON;if(S.phase==='ccg')return S.ccg.find(isMine)||null;if(S.phase==='div')return S.div.find(isMine)||null;if(S.phase==='semi')return S.semis.find(isMine)||null;if(S.phase==='final')return isMine(S.final)?S.final:null;
 const wk=S.sched[S.week];return wk&&wk.find(isMine)}
function featured(){const S=SEASON,un=a=>a.filter(g=>!g.res);if(scrimPending(S))return S.scrim;if(S.phase==='ccg'){const U=un(S.ccg);return U.find(isMine)||U.find(c=>c.conf===myConf().id)||U[0]||S.ccg.find(isMine)||S.ccg[0]}
 if(S.phase==='div'){const U=un(S.div);return U.find(isMine)||U.find(g=>g.div===myDiv().id)||U[0]||S.div[0]}if(S.phase==='semi'){const U=S.semis.filter(g=>!g.res);return U.find(isMine)||U[0]||S.semis[0]}if(S.phase==='final')return S.final;return myGame()}
const KIND_CODE={ccg:1,div:2,semi:2,final:3};
// weather for a league game: by the calendar (week of the season, then playoff round); the State final is indoors
function wxFor(g){if(g.wx)return g.wx;const k=g.kind||'reg',wk=SEASON?SEASON.week:0;const st=k==='scrim'?0:k==='div'?3:k==='semi'?4:k==='ccg'?2:wk<=2?0:wk<=4?1:2;return g.wx=rollWeather(st,k==='final')}
function simGame(g){const gm=newGame(TM(g.h),TM(g.a));setWeather(gm,wxFor(g));gm.yearAdj={h:yAdj(g.h),a:yAdj(g.a)};simToEnd(gm);g.res={hs:gm.score.h,as:gm.score.a,ot:gm.ot};if(g.kind!=='scrim')accStats(gm,g.kind)}
// ---- SEASON STATS ----
// Team totals and every player's season line, accumulated from each game (regular season + postseason).
const PSF=['cmp','att','py','ptd','int','car','ry','rtd','rec','recy','rectd','tkl','sk','dint','fgm','fga','xpm','xpa'];
function accStats(gm,kind){const S=SEASON;if(!S)return;h2hAdd(gm.h.id,gm.a.id,gm.score.h,gm.score.a,KIND_CODE[kind]||0,seasonYear(S.num));const st=S.stats||(S.stats={t:{},p:{}});
 for(const side of['h','a']){const t=side==='h'?gm.h:gm.a,o=side==='h'?'a':'h',ts=gm.stats[side];
  const r=st.t[t.id]||(st.t[t.id]={gp:0,w:0,pf:0,pa:0,py:0,ry:0,to:0,tk:0,sk:0});
  r.gp++;if(gm.score[side]>gm.score[o])r.w++;r.pf+=gm.score[side];r.pa+=gm.score[o];r.py+=ts.py;r.ry+=ts.ry;r.to+=ts.to;r.tk+=gm.stats[o].to;r.sk+=ts.sacks}
 for(const k in gm.ps){const x=gm.ps[k],p=x.p;if(!PSF.some(f=>x[f]))continue;
  const r=st.p[p.id]||(st.p[p.id]={n:(p.first?p.first[0]+'. ':'')+p.last,t:p.team,pos:p.pos,num:p.num,real:!!p.real,gp:0});r.gp++;
  for(const f of PSF)if(x[f])r[f]=(r[f]||0)+x[f]}}
let statScope=null,statCat='team';
const STAT_CATS=[['team','Team'],['pass','Passing'],['rush','Rushing'],['rec','Receiving'],['def','Defense'],['kick','Kicking']];
const pct=(a,b)=>b?(a/b*100).toFixed(0)+'%':'—',avg=(a,b)=>b?(a/b).toFixed(1):'—';
const STAT_DEF={
 pass:{f:r=>r.att,sort:r=>r.py||0,cols:['Cmp/Att','Pct','Yds','TD','INT'],row:r=>[(r.cmp||0)+'/'+(r.att||0),pct(r.cmp||0,r.att),r.py||0,r.ptd||0,r.int||0]},
 rush:{f:r=>r.car,sort:r=>r.ry||0,cols:['Car','Yds','Avg','TD'],row:r=>[r.car||0,r.ry||0,avg(r.ry||0,r.car),r.rtd||0]},
 rec:{f:r=>r.rec,sort:r=>r.recy||0,cols:['Rec','Yds','Avg','TD'],row:r=>[r.rec||0,r.recy||0,avg(r.recy||0,r.rec),r.rectd||0]},
 def:{f:r=>r.tkl||r.sk||r.dint,sort:r=>(r.tkl||0)+(r.sk||0)*3+(r.dint||0)*3,cols:['Tkl','Sacks','INT'],row:r=>[r.tkl||0,r.sk||0,r.dint||0]},
 kick:{f:r=>r.fga||r.xpa,sort:r=>(r.fgm||0)*3+(r.xpm||0),cols:['FG','FG%','XP','Pts'],row:r=>[(r.fgm||0)+'/'+(r.fga||0),pct(r.fgm||0,r.fga),(r.xpm||0)+'/'+(r.xpa||0),(r.fgm||0)*3+(r.xpm||0)]}};
function scopeTeams(sc){if(sc==='ALL')return LEAGUE.confs.flatMap(c=>c.teams);if(sc==='ME')return[SEASON.team];return confById(sc).teams}
function statsBody(){const S=SEASON,st=S.stats||{t:{},p:{}},sc=statScope||myConf().id,ids=new Set(scopeTeams(sc));
 const scopes=[['ME','My Team'],...LEAGUE.confs.map(c=>[c.id,c.name.replace(' Conference','')]),['ALL','All']];
 let h=`<div class="s-tabs">${scopes.map(([k,l])=>`<button data-sscope="${k}" class="${k===sc?'on':''}">${l}</button>`).join('')}</div>
  <div class="s-tabs">${STAT_CATS.map(([k,l])=>`<button data-scat="${k}" class="${k===statCat?'on':''}">${l}</button>`).join('')}</div>`;
 if(!Object.keys(st.t).length)return h+'<p class="s-soon">No games played yet. Stats fill in as the season goes.</p>';
 if(statCat==='team'){const rows=[...ids].map(id=>({id,...(st.t[id]||{gp:0,w:0,pf:0,pa:0,py:0,ry:0,to:0,tk:0,sk:0})})).sort((a,b)=>(b.pf-b.pa)/(b.gp||1)-(a.pf-a.pa)/(a.gp||1));
  return h+`<table class="s-tbl"><tr><th class="l">Team</th><th>G</th><th>PPG</th><th>OPP</th><th>Pass/g</th><th>Rush/g</th><th>TO</th><th>TA</th><th>Sk</th></tr>${rows.map(r=>`<tr class="${r.id===S.team?'me':''}"><td class="l">${logo(TM(r.id),18)} ${esc(TM(r.id).abbr)}</td><td>${r.gp}</td><td>${avg(r.pf,r.gp)}</td><td>${avg(r.pa,r.gp)}</td><td>${r.gp?Math.round(r.py/r.gp):'—'}</td><td>${r.gp?Math.round(r.ry/r.gp):'—'}</td><td>${r.to}</td><td>${r.tk}</td><td>${r.sk}</td></tr>`).join('')}</table><p class="s-soon">PPG/OPP = points scored/allowed per game · TO = giveaways · TA = takeaways · Sk = sacks by the defense</p>`}
 const D=STAT_DEF[statCat],list=Object.values(st.p).filter(r=>ids.has(r.t)&&D.f(r)).sort((a,b)=>D.sort(b)-D.sort(a)).slice(0,sc==='ME'?40:25);
 if(!list.length)return h+'<p class="s-soon">No stats in this category yet.</p>';
 return h+`<table class="s-tbl"><tr><th></th><th class="l">Player</th><th>G</th>${D.cols.map(c=>`<th>${c}</th>`).join('')}</tr>${list.map((r,i)=>`<tr class="${r.t===S.team?'me':''}"><td>${i+1}</td><td class="l">${logo(TM(r.t),16)} ${r.num!=null?'#'+r.num+' ':''}${esc(r.n)}</td><td>${r.gp}</td>${D.row(r).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</table>`}
function leadersHtml(){const st=SEASON.stats;if(!st)return'';const all=Object.values(st.p),top=(f,sort)=>all.filter(f).sort((a,b)=>sort(b)-sort(a))[0];
 const L=[['Passing',top(r=>r.att,r=>r.py||0),r=>(r.py||0)+' yds, '+(r.ptd||0)+' TD'],['Rushing',top(r=>r.car,r=>r.ry||0),r=>(r.ry||0)+' yds, '+(r.rtd||0)+' TD'],['Receiving',top(r=>r.rec,r=>r.recy||0),r=>(r.recy||0)+' yds, '+(r.rectd||0)+' TD'],
  ['Tackles',top(r=>r.tkl,r=>r.tkl),r=>r.tkl+' tkl'],['Sacks',top(r=>r.sk,r=>r.sk),r=>r.sk+' sacks'],['Interceptions',top(r=>r.dint,r=>r.dint),r=>r.dint+' INT']].filter(x=>x[1]);
 return`<div class="s-lead"><div class="kick" style="font-size:11px">Season leaders</div>${L.map(([k,r,f])=>`<div>${k}: ${logo(TM(r.t),14)} <b>${esc(r.n)}</b> (${esc(TM(r.t).abbr)}) ${f(r)}</div>`).join('')}<button data-stab="stats" style="margin-top:6px">Full season stats</button></div>`}
const winner=g=>g.res.hs>g.res.as?g.h:g.a;
const recScore=id=>{const st=standings(confOfId(id).id).find(r=>r.id===id);return(st.w-st.l)*1000+(st.pf-st.pa)};
const pairUp=(a,b,extra)=>{const h=recScore(a)>=recScore(b)?a:b;return Object.assign({h,a:h===a?b:a},extra)};
function gameTitle(g){if(!g)return null;if(g.kind==='scrim')return'Preseason Scrimmage';if(g.kind==='ccg')return confById(g.conf).name+' Championship';if(g.kind==='div')return LEAGUE.divs.find(d=>d.id===g.div).game;if(g.kind==='semi')return'Sectional Championship';if(g.kind==='final')return LEAGUE.finalName;return null}
function finishWeek(){const S=SEASON;S.prevPower=powerRank().map(r=>r.id);for(const g of S.sched[S.week])if(!g.res)simGame(g);S.week++;
 if(S.week>=S.sched.length){S.phase='ccg';S.ccg=[];finishCCG();return}saveSeason()}
function finishCCG(){const S=SEASON;for(const c of S.ccg)if(!c.res)simGame(c);S.ccg.forEach(c=>{S.champs[c.conf]=winner(c);careerAdd(winner(c),'cf')});
 // Conference champion = best conference record (tiebreak: head-to-head, then overall record, then point differential). No title game.
 if(!S.ccg.length)for(const c of LEAGUE.confs){const w=standings(c.id)[0].id;S.champs[c.id]=w;careerAdd(w,'cf')}S.div=[];S.divChamps={};
 for(const d of LEAGUE.divs){const ch=d.confs.map(c=>S.champs[c]);if(ch.length===2)S.div.push(pairUp(ch[0],ch[1],{div:d.id,kind:'div'}));else S.divChamps[d.id]=ch[0]}
 S.phase='div';if(!S.div.length)finishDiv();else saveSeason()}
// Sectional pairings rotate every year (new seasons only; canon history keeps the classic pairing):
//  classic: Northern Indiana vs Crossroads (the Penn-Carmel semi-state)  ·  then Northern Indiana vs Hoosier  ·  then Northern Indiana vs Wabash Valley
const SECTIONAL_ROTATION=[[['ND','MW'],['EW','PV']],[['ND','EW'],['MW','PV']],[['ND','PV'],['MW','EW']]];
function sectionalsFor(S){const y=S?seasonYear(S.num):FIRST_SEASON_YEAR;return SECTIONAL_ROTATION[((y-FIRST_SEASON_YEAR)%3+3)%3]}
function finishDiv(){const S=SEASON;for(const g of S.div)if(!g.res)simGame(g);S.div.forEach(g=>{S.divChamps[g.div]=winner(g);careerAdd(winner(g),'rg')});
 const ch=LEAGUE.divs.map(d=>S.divChamps[d.id]);
 if(ch.length===2){S.final=pairUp(ch[0],ch[1],{kind:'final'});S.phase='final';saveSeason();return}
 S.semis=sectionalsFor(S).map(([x,y],k)=>pairUp(S.divChamps[x],S.divChamps[y],{kind:'semi',sid:k+1}));S.phase='semi';saveSeason()}
function finishSemi(){const S=SEASON;for(const g of S.semis)if(!g.res)simGame(g);S.final=pairUp(winner(S.semis[0]),winner(S.semis[1]),{kind:'final'});S.phase='final';saveSeason()}
function finishFinal(){const S=SEASON;if(!S.final.res)simGame(S.final);S.champ=winner(S.final);careerAdd(S.champ,'st');careerAdd(S.final.h,'sf');careerAdd(S.final.a,'sf');
 const Y=seasonYear(S.num),H=hst(),code={};for(const g of S.ccg){code[g.h]=Math.max(code[g.h]||0,1);code[g.a]=Math.max(code[g.a]||0,1)}for(const c in S.champs)code[S.champs[c]]=2;for(const d in S.divChamps)code[S.divChamps[d]]=3;code[S.champ]=4;code[S.champ===S.final.h?S.final.a:S.final.h]=5;
 for(const r of Object.values(overallRows())){careerAdd(r.id,'w',r.w);careerAdd(r.id,'l',r.l);(H.yrs[r.id]=H.yrs[r.id]||[]).push([Y,r.w,r.l,code[r.id]||0])}
 const f=S.final,fl=S.champ===f.h?f.a:f.h;H.finals.push([Y,S.champ,fl,Math.max(f.res.hs,f.res.as),Math.min(f.res.hs,f.res.as),f.res.ot?1:0]);S.phase='done';saveSeason()}
function advanceAll(){let guard=0;if(scrimPending(SEASON))simGame(SEASON.scrim);while(SEASON.phase!=='done'&&guard++<60){if(SEASON.phase==='regular'){const g=myGame();if(g&&!g.res)simGame(g);finishWeek()}else if(SEASON.phase==='ccg')finishCCG();else if(SEASON.phase==='div')finishDiv();else if(SEASON.phase==='semi')finishSemi();else finishFinal()}}
let seasonTab='stand',standConf=null;
// Back to the season in progress (used after a game); the Season menu button uses openSeason, which shows the saves list.
// ---------- Super Sim: watch the season game after game (your games, then every playoff game through State) ----------
let SUPER=false;
function superStart(){SUPER=true;superNext()}
function superStop(){SUPER=false;const c=$('#superChip');if(c)c.style.display='none'}
function superNext(){if(!SUPER)return;const S=SEASON;let guard=0;
 while(guard++<40){if(S.phase==='done'){superStop();seasonTab='brk';show('season');renderSeason();const ch=TM(S.champ);bToast('Super Sim done · '+ch.school+' '+ch.name+' win State');return}
  if(S.phase==='ccg'){finishCCG();continue}
  if(S.phase==='regular'&&!scrimPending(S)&&!myGame()){finishWeek();continue}
  const g=featured();if(!g||g.res){if(S.phase==='regular')finishWeek();else if(S.phase==='div')finishDiv();else if(S.phase==='semi')finishSemi();else if(S.phase==='final')finishFinal();continue}
  playSeasonGame(true,g);const c=$('#superChip');if(c)c.style.display='block';return}}
// Rosters follow the season year: seniors graduate and new classes arrive each Next Season.
function syncRoster(){if(!SEASON_CTX)return;const y=SEASON?seasonYear(SEASON.num):2026;const ex=(SEASON&&SEASON.hist&&SEASON.hist.duellOut)||0,exCh=typeof EXPEL_YEAR!=='undefined'&&EXPEL_YEAR!==ex;if(exCh)EXPEL_YEAR=ex;if(typeof ROSTER_YEAR!=='undefined'&&(ROSTER_YEAR!==y||exCh)){ROSTER_YEAR=y;buildAll();if(typeof v3NumC!=='undefined')for(const k in v3NumC)delete v3NumC[k]}try{coachesInit();applyCoaches()}catch(e){console.error(e)}}
function resumeSeason(){if(SEASON){show('season');renderSeason()}else openSeason()}
function openSeason(){if(!SAVES.list.length){pickTeamFor('season');return}openSaves()}
const BIG4={CARMEL:1,CATH:1,BD:1,WC:1};
const resTxt=(g,id)=>{if(!g.res)return'';const home=g.h===id,my=home?g.res.hs:g.res.as,th=home?g.res.as:g.res.hs;const pw=g.res.hs>g.res.as?g.h:g.a,pl=pw===g.h?g.a:g.h,big=pw==='PENN'&&BIG4[pl]&&g.kind&&g.kind!=='scrim';return`<b class="${my>th?'w':'l'}">${my>th?'W':'L'} ${my}-${th}${g.res.ot?' OT':''}</b>${big?' <span style="color:#ffcf3d">· Penn takes down a Big 4 program!</span>':''}`};
function matchCard(g,title,sub,btns){return`<div class="s-week">${title}</div><div class="s-match">${logo(TM(g.a),58)}<div><div class="s-vs">${sub}</div><div class="s-at">${g.kind==='final'?'Lucas Oil Stadium · Indianapolis':esc(stadiumFor(TM(g.h)).venue)}</div><div class="s-opp" style="color:#93c5fd">${seriesLine(g.a,g.h,true)}</div></div>${logo(TM(g.h),58)}</div><div class="btns">${btns}</div>`}
// ---- OVERALL STANDINGS / POWER RANKINGS / BRACKET ----
function allGames(){const S=SEASON;return[...S.sched.flat(),...(S.ccg||[]),...(S.div||[]),...(S.semis||[]),S.final].filter(g=>g&&g.res)}
function overallRows(){const rows={};for(const c of LEAGUE.confs)for(const id of c.teams)rows[id]={id,conf:c.id,w:0,l:0,pf:0,pa:0,opp:[]};
 for(const g of allGames()){const {hs,as}=g.res;for(const [me,th,a,b] of [[g.h,g.a,hs,as],[g.a,g.h,as,hs]]){const r=rows[me];if(!r)continue;r.pf+=a;r.pa+=b;r.opp.push(th);if(a>b)r.w++;else r.l++}}
 return rows}
// Conference pedigree: Midstate's history earns its teams extra weight in the rankings.
const CONF_PEDIGREE={MS:5};
function confPowerFrom(rows){return LEAGUE.confs.map(c=>{const T=c.teams.map(id=>rows[id]).filter(Boolean),avg=T.reduce((a,r)=>a+r.base,0)/T.length,w=T.reduce((a,r)=>a+r.w,0),l=T.reduce((a,r)=>a+r.l,0);
  // wins outside the conference (playoffs) count extra: they're the only head-to-head proof between conferences
  let xw=0,xl=0;for(const g of allGames()){const ch=confOf(g.h),ca=confOf(g.a);if(ch===ca)continue;const hw=g.res.hs>g.res.as;if(ch===c.id){hw?xw++:xl++}if(ca===c.id){hw?xl++:xw++}}
  return{id:c.id,name:c.name,avg,w,l,xw,xl,power:avg+(CONF_PEDIGREE[c.id]||0)+(xw-xl)*1.2}}).sort((a,b)=>b.power-a.power)}
function confOf(id){const c=LEAGUE.confs.find(c=>c.teams.includes(id));return c&&c.id}
