document.addEventListener('click',e=>{const b=e.target.closest('[data-stab]');if(b){seasonTab=b.dataset.stab;renderSeason()}const c=e.target.closest('[data-sconf]');if(c){standConf=c.dataset.sconf;renderSeason()}const sc=e.target.closest('[data-sscope]');if(sc){statScope=sc.dataset.sscope;renderSeason()}const ca=e.target.closest('[data-scat]');if(ca){statCat=ca.dataset.scat;renderSeason()}const bw=e.target.closest('[data-watch]');if(bw){const [k,key]=bw.dataset.watch.split('|'),S=SEASON,g=k==='ccg'?S.ccg.find(x=>x.conf===key):k==='div'?S.div.find(x=>x.div===key):k==='semi'?S.semis.find(x=>String(x.sid)===key):S.final;if(g&&!g.res)playSeasonGame(!isMine(g),g);return}const pm=e.target.closest('[data-pmode]');if(pm){powMode=pm.dataset.pmode;renderSeason()}const pg=e.target.closest('[data-prog]');if(pg){programModal(pg.dataset.prog)}if(e.target.id==='vsRun'){const a=vsA||SEASON.team,b=vsB||(rivalOf(a)||(a==='PENN'?'MISH':'PENN'));let w=0,sa=0,sb=0;for(let i=0;i<500;i++){const g=i%2?newGame(TM(a),TM(b)):newGame(TM(b),TM(a));simToEnd(g);const as=i%2?g.score.h:g.score.a,bs=i%2?g.score.a:g.score.h;sa+=as;sb+=bs;if(as>bs)w++}vsSim={k:a+b,p:Math.round(w/5),sa:Math.round(sa/500),sb:Math.round(sb/500)};renderSeason()}});
function playSeasonGame(live,g0){AUTO=!!live;const g=g0||featured(),mine=isMine(g),home=g.h===SEASON.team;if(!mine)AUTO=true;if(pendingRebuild){pendingRebuild=false;buildAll()}
 const title=gameTitle(g);
 U=mine?(home?'h':'a'):'none';G=newGame(TM(g.h),TM(g.a));setWeather(G,wxFor(g));G.yearAdj={h:yAdj(g.h),a:yAdj(g.a)};if(U!=='none')G.edge3d={s:U,v:3,on:typeof V3!=='undefined'&&V3.on};G.venue=g.kind==='final'?STATE_VENUE:TM(g.h);/* farm field venue switched off for now: it would not load on iPad */G.season0=1;G.season={week:SEASON.week,kind:g.kind||'reg',conf:g.conf,div:g.div,sid:g.sid,title,ccg:!!title&&g.kind!=='scrim'};G.trash=trashTalk(G);lastRes=null;show('game');if(typeof annIntro==='function')annIntro(G);$('#playText').textContent=G.log[0];renderGame();cutscene('intro',G.h,()=>{if(AUTO)autoStep()})}
function recordSeasonGame(){if(!G||!G.season||G.season.recorded)return;const S=SEASON,k=G.season.kind,res={hs:G.score.h,as:G.score.a,ot:G.ot};
 if(k==='scrim'){if(S.scrim&&!S.scrim.res){S.scrim.res=res;G.season.recorded=true;saveSeason()}return}
 if(k==='ccg'){if(S.phase!=='ccg')return;const g=S.ccg.find(c=>c.conf===G.season.conf);if(!g||g.res)return;g.res=res;G.season.recorded=true;accStats(G,G.season.kind);if(S.ccg.every(c=>c.res))finishCCG();else saveSeason();return}
 if(k==='div'){if(S.phase!=='div')return;const g=S.div.find(c=>c.div===G.season.div);if(!g||g.res)return;g.res=res;G.season.recorded=true;accStats(G,G.season.kind);if(S.div.every(c=>c.res))finishDiv();else saveSeason();return}
 if(k==='semi'){if(S.phase!=='semi')return;const g=S.semis.find(x=>x.sid===G.season.sid);if(!g||g.res)return;g.res=res;G.season.recorded=true;accStats(G,G.season.kind);if(S.semis.every(x=>x.res))finishSemi();else saveSeason();return}
 if(k==='final'){if(S.phase!=='final'||S.final.res)return;S.final.res=res;G.season.recorded=true;accStats(G,G.season.kind);finishFinal();return}
 if(G.season.week!==S.week||S.phase!=='regular')return;const g=myGame();if(!g)return;g.res=res;G.season.recorded=true;accStats(G,G.season.kind);finishWeek()}
