// ===================== LEGENDS =====================
// Every school's all-time greats. Canon legends (1826-2025) are generated from the real canon seasons (same names every time,
// more legends for programs with more titles) and never change any result. Players from your own seasons join when they
// graduate with a great career. Stat lines are scaled to this game's stat economy so Schrader can be compared fairly.
// Names you've set for specific canon legends (id = school:final year)
const LEGEND_NAMES={};
const LEG_POS=[['QB',30],['RB',24],['WR',12],['LB',12],['DL',9],['CB',5],['S',5],['TE',3]],LEG_CACHE={};
function lgRng(seed){let h=2166136261;for(const c of String(seed))h=Math.imul(h^c.charCodeAt(0),16777619);return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function legScore(L){const s=L.stats,pts=(s.py||0)/450+(s.ptd||0)/5+(s.ry||0)/260+(s.rtd||0)/3.5+(s.recy||0)/170+(s.rectd||0)/2.6+(s.tkl||0)/7+(s.sk||0)/1.6+(s.dint||0)/1.1;
 return Math.round(L.st.length*30+L.ru.length*14+(L.rg||0)*5+(L.cf||0)*3+(L.w-L.l)*.8+pts)}
function legCareer(id,from,to){let w=0,l=0,cf=0,rg=0;const st=[],ru=[];for(const y of yearsOf(id)){if(y[0]<from||y[0]>to)continue;w+=y[1];l+=y[2];if(y[3]===4)st.push(y[0]);if(y[3]===5)ru.push(y[0]);if(y[3]>=2)cf++;if(y[3]>=3)rg++}return{w,l,st,ru,cf,rg}}
function makeLegend(id,Yr){const r=lgRng(id+':legend:'+Yr),pk=a=>a[Math.floor(r()*a.length)];let x=r()*100,pos='QB';for(const [p,w] of LEG_POS){if((x-=w)<0){pos=p;break}}
 const yrs=2+(r()<.6?1:0),from=Yr-yrs,c=legCareer(id,from,Yr),q=c.w+c.l?c.w/(c.w+c.l):.5,n=Yr-from+1,f=(b,sp)=>{let t=0;for(let i=0;i<n;i++)t+=b*(.55+q*.55)+r()*sp;return Math.round(t)},s={};
 if(pos==='QB'){s.py=f(1450,700);s.ptd=Math.round(s.py/(85+r()*25));s.ry=f(120,260)}else if(pos==='RB'){s.ry=f(760,520);s.rtd=Math.round(s.ry/(72+r()*20))}
 else if(pos==='WR'||pos==='TE'){s.recy=f(pos==='TE'?380:520,330);s.rectd=Math.round(s.recy/(62+r()*18))}else if(pos==='LB'){s.tkl=f(22,12);s.sk=f(2,3)}else if(pos==='DL'){s.tkl=f(15,10);s.sk=f(4,4)}else{s.tkl=f(16,10);s.dint=f(2.5,3.5)}
 const nums=POS[pos==='TE'?'TE':pos].nums.flatMap(([a,b])=>Array.from({length:b-a+1},(_,i)=>a+i));
 const L={id:id+':'+Yr,t:id,first:pk(FIRST),last:pk(LAST),num:pk(nums),pos,from,to:Yr,...c,stats:s,canon:true};Object.assign(L,LEGEND_NAMES[L.id]||{});L.score=legScore(L);return L}
function canonLegends(id){if(LEG_CACHE[id])return LEG_CACHE[id];const Y=yearsOf(id).filter(y=>y[0]<FIRST_SEASON_YEAR),sc=y=>({4:100,5:60,3:35,2:18}[y[3]]||0)+(y[1]+y[2]?y[1]/(y[1]+y[2]):0)*25;
 const st=Y.filter(y=>y[3]===4).length,K=Math.min(10,3+Math.round(st*.3+Y.filter(y=>y[3]>=3).length*.08)),picked=[];
 for(const y of [...Y].sort((a,b)=>sc(b)-sc(a))){if(picked.length>=K)break;if(picked.some(p=>Math.abs(p[0]-y[0])<4))continue;picked.push(y)}
 return LEG_CACHE[id]=picked.map(y=>makeLegend(id,y[0]))}
function legendsOf(id){return canonLegends(id).concat((hst().legends||[]).filter(L=>L.t===id)).sort((a,b)=>b.score-a.score)}
function allLegends(){return TEAMS.flatMap(t=>legendsOf(t.id)).sort((a,b)=>b.score-a.score)}
// Mr. Football: the top legend whose career ended that year
function mrFootball(){const m={};for(const L of allLegends()){if(!m[L.to]||m[L.to].score<L.score)m[L.to]=L}return new Set(Object.values(m).map(L=>L.id))}
// At Next Season: log this year's top performers, then graduating seniors with great careers become legends.
function recordCareers(S){const H=S.hist||(S.hist={t:{},h2h:{},yrs:{},finals:[]}),car=H.car||(H.car={}),Y=seasonYear(S.num),P=Object.entries((S.stats&&S.stats.p)||{});
 const perf=r=>(r.py||0)/450+(r.ptd||0)/5+(r.ry||0)/260+(r.rtd||0)/3.5+(r.recy||0)/170+(r.rectd||0)/2.6+(r.tkl||0)/7+(r.sk||0)/1.6+(r.dint||0)/1.1;
 const byTeam={};for(const [pid,r] of P)(byTeam[r.t]=byTeam[r.t]||[]).push([pid,r]);
 for(const t in byTeam){const top=byTeam[t].sort((a,b)=>perf(b[1])-perf(a[1])).slice(0,t===S.team?8:4);const T=TM(t);
  for(const [pid,r] of top){const p=T&&T.players.find(x=>x.id===pid);if(!p)continue;const key=t+'|'+p.first+' '+p.last+'|'+p.pos;const c=car[key]||(car[key]={t,first:p.first,last:p.last,num:p.num,pos:p.pos,from:Y,stats:{},real:!!p.real});
   c.to=Y;c.num=p.num;for(const f of['py','ptd','ry','rtd','recy','rectd','tkl','sk','dint'])if(r[f])c.stats[f]=(c.stats[f]||0)+r[f];c.yr=p.yr}}
 const legs=H.legends||(H.legends=[]),cand={};
 for(const key in car){const c=car[key];if(c.to!==Y||c.yr!=='SR')continue;const cr=legCareer(c.t,c.from,c.to),L={id:key+':'+Y,t:c.t,first:c.first,last:c.last,num:c.num,pos:c.pos,from:c.from,to:c.to,...cr,stats:c.stats,canon:false,real:c.real};L.score=legScore(L);
  const bar=Math.min(...canonLegends(c.t).map(x=>x.score),9999);if(L.score>=bar||L.st.length||(c.t===S.team&&L.score>=bar*.8))(cand[c.t]=cand[c.t]||[]).push(L);delete car[key]}
 // at most one new legend per school per year (two for your team), best first
 for(const t in cand){cand[t].sort((a,b)=>b.score-a.score);legs.push(...cand[t].slice(0,t===S.team?2:1))}
 for(const key in car)if(car[key].to<Y-1)delete car[key]}
const LEG_STAT=L=>{const s=L.stats,o=[];if(s.py)o.push(s.py.toLocaleString()+' pass yds, '+(s.ptd||0)+' TD');if(s.ry&&L.pos!=='QB')o.push(s.ry.toLocaleString()+' rush yds, '+(s.rtd||0)+' TD');if(s.recy)o.push(s.recy.toLocaleString()+' rec yds, '+(s.rectd||0)+' TD');
 if(s.tkl)o.push(s.tkl+' tkl');if(s.sk)o.push(s.sk+' sacks');if(s.dint)o.push(s.dint+' INT');return o.join(' · ')};
let legScope='ALL';
function legendsBody(){const mf=mrFootball(),list=legScope==='ALL'?allLegends().slice(0,25):legendsOf(legScope);
 const opts=[...TEAMS].sort((a,b)=>a.school.localeCompare(b.school)).map(t=>`<option value="${t.id}" ${legScope===t.id?'selected':''}>${esc(t.school)}</option>`).join('');
 return`<div style="display:flex;align-items:center;gap:8px;margin:4px 0 8px"><select id="legDD" style="background:#151a22;color:#ffcf3d;border:1px solid #39404c;border-radius:6px;font:600 12px Inter,sans-serif;padding:4px"><option value="ALL">All-Time Top 25 (league)</option>${opts}</select><span class="s-opp">${legScope==='ALL'?'The greatest players in league history':'Greatest players in '+esc(TM(legScope).school)+' history'}</span></div>
 <table class="s-tbl"><tr><th>#</th><th class="l">Player</th>${legScope==='ALL'?'<th class="l">School</th>':''}<th>Pos</th><th>Years</th><th class="l">Career</th><th class="l">Honors</th></tr>${list.map((L,i)=>`<tr${L.t===SEASON.team?' class="me"':''}><td>${i+1}</td><td class="l"><b>${esc(L.first+' '+L.last)}</b> #${L.num}${L.canon?'':' <span class="chip l">YOUR ERA</span>'}</td>${legScope==='ALL'?`<td class="l">${logo(TM(L.t),16)} ${esc(TM(L.t).abbr)}</td>`:''}<td>${L.pos}</td><td>${L.from}–${String(L.to).slice(2)}</td><td class="l" style="font-size:11px">${LEG_STAT(L)} · ${L.w}-${L.l}</td><td class="l" style="font-size:11px">${[mf.has(L.id)?'🏅 Mr. Football '+L.to:'',L.st.length?'🏆 State '+L.st.join(', '):'',L.ru.length?'💍 State runner-up '+L.ru.join(', '):''].filter(Boolean).join(' · ')||(L.cf?L.cf+'× conf champ':'')}</td></tr>`).join('')}</table>`}
